To safely and correctly evaluate a mathematical expression adhering to the order of operations, parentheses, and negative numbers in Python without using the insecure `eval()` function, we can implement a **Shunting-Yard algorithm** (to convert infix notation to postfix/Reverse Polish Notation) followed by a **postfix expression evaluator**.

Here is the complete Python function:

```python
def eval_expression(expr: str) -> float:
    def get_tokens(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            char = s[i]
            if char.isspace():
                i += 1
                continue

            # Handle numbers (including decimals and negative numbers)
            if char.isdigit() or char == '.':
                num_str = []
                while i < n and (s[i].isdigit() or s[i] == '.'):
                    num_str.append(s[i])
                    i += 1
                tokens.append(float(''.join(num_str)))
            elif char in "+-*/()":
                # Check for unary minus (negative numbers)
                if char == '-' and (not tokens or (isinstance(tokens[-1], str) and tokens[-1] == '(')):
                    i += 1
                    # Skip spaces after unary minus
                    while i < n and s[i].isspace():
                        i += 1
                    if i < n and (s[i].isdigit() or s[i] == '.'):
                        num_str = []
                        while i < n and (s[i].isdigit() or s[i] == '.'):
                            num_str.append(s[i])
                            i += 1
                        tokens.append(-float(''.join(num_str)))
                    else:
                        raise ValueError(f"Invalid syntax near index {i}")
                else:
                    tokens.append(char)
                    i += 1
            else:
                raise ValueError(f"Invalid character '{char}' in expression")
        return tokens

    tokens = get_tokens(expr)

    # Shunting-yard algorithm to convert to RPN (Postfix)
    output_queue = []
    operator_stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if isinstance(token, (int, float)):
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] in precedence and
                   precedence[operator_stack[-1]] >= precedence[token]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses")
            operator_stack.pop() # Remove '('

    while operator_stack:
        op = operator_stack.pop()
        if op == '(':
            raise ValueError("Mismatched parentheses")
        output_queue.append(op)

    # Evaluate RPN
    eval_stack = []
    for token in output_queue:
        if isinstance(token, (int, float)):
            eval_stack.append(token)
        else:
            if len(eval_stack) < 2:
                raise ValueError("Invalid expression")
            b = eval_stack.pop()
            a = eval_stack.pop()

            if token == '+':
                eval_stack.append(a + b)
            elif token == '-':
                eval_stack.append(a - b)
            elif token == '*':
                eval_stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                eval_stack.append(a / b)

    if len(eval_stack) != 1:
        raise ValueError("Invalid expression")

    result = eval_stack[0]
    # Return as int if it's a whole number, otherwise float
    return int(result) if result.is_integer() else result
```

### Example Usage:

```python
print(eval_expression("3 + 4 * (2 - 1)"))       # Output: 7
print(eval_expression("-5 + 3 * (-2 + 4)"))     # Output: 1
print(eval_expression("10 / (5 - 5)"))          # Raises ZeroDivisionError
```

